```js
console.log(1 + '2');
console.log('6' - 2);
console.log('5' == 5);
console.log('5' === 5);
```

solution.code:
function isBlank(value) {
  if (value === null) {
    return true;
  }
  if (typeof value === 'string') {
    return value.trim() === '';
  }
  return false;
}

grading.starterCode:
function isBlank(value) {
  // The tempting shortcut. It also calls 0 and false blank.
  return !value;
}

